import {TODAY,addDays,dayOf,minutes,clock,available,epoch,seed,normalizeData,subscriptionStats,subscriptionFromForm,normalizeBranding,brandingFromForm,brandVariables,isBrandColor,contrastText,BRAND_COLOR_KEYS,BRAND_FONTS,isBrandFont} from './core.js?v=0.15.1';
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2 M7 14h2 M13 14h2 M7 18h2',layers:'m12 3 9 5-9 5-9-5 9-5 M3 12l9 5 9-5 M3 16l9 5 9-5',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',code:'m8 6-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',mail:'M3 5h18v14H3z m0 0 9 7 9-7',chart:'M4 20V4 M4 20h17 M8 16v-4 M13 16V8 M18 16V3',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 4a4 4 0 0 1 0 7 M22 21v-2a4 4 0 0 0-3-4',arrow:'M4 12h15 m-5-5 5 5-5 5',external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',plus:'M12 5v14 M5 12h14',chevron:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',close:'m6 6 12 12 M6 18 18 6',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',euro:'M18 5c-8-6-14 7-7 14 2 2 5 1 7 0 M4 9h12 M4 14h10',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',leaf:'M20 3C6 2 1 12 7 18c6 6 15-1 13-15z M4 21 15 10',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v2 M12 21v2 M1 12h2 M21 12h2 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',chat:'M21 4H3v13h4v4l5-4h9z M7 9h10 M7 13h6',home:'m3 10 9-8 9 8 M5 9v12h14V9 M9 21v-7h6v7',wind:'M3 8h12a3 3 0 1 0-3-3 M3 12h16a3 3 0 1 1-3 3 M3 16h7a3 3 0 1 1-3 3',tool:'M14 4a6 6 0 0 0-6 8L2 18l4 4 6-6a6 6 0 0 0 8-8l-4 4-4-4 4-4z',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',more:'M5 12h.01 M12 12h.01 M19 12h.01',copy:'M9 9h12v12H9z M15 9V3H3v12h6',pin:'M12 22s8-8 8-14a8 8 0 0 0-16 0c0 6 8 14 8 14z M12 6a2 2 0 1 0 0 4 2 2 0 0 0 0-4',kanban:'M3 3h18v18H3z M9 3v18 M15 3v18 M5 7h2 M11 7h2 M17 7h2 M5 11h2',book:'M3 3h7l2 2 2-2h7v17h-7l-2 1-2-1H3z M12 5v16',menu:'M4 6h16 M4 12h16 M4 18h16',shield:'m12 3 9 3v6c0 5-9 9-9 9s-9-4-9-9V6z m-4 9 3 3 5-6',download:'M12 3v12 m-5-5 5 5 5-5 M3 16v5h18v-5',edit:'m4 16 12-12 4 4-12 12-5 1z M14 6l4 4'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=u=>{try{const x=new URL(u);return /^https?:$/.test(x.protocol)?x.href:''}catch{return ''}};
const money=n=>new Intl.NumberFormat('nl-BE',{style:'currency',currency:'EUR',maximumFractionDigits:Number.isInteger(n)?0:2}).format(n||0);
const fmt=(d,opt={day:'numeric',month:'long'})=>new Intl.DateTimeFormat('nl-BE',{...opt,timeZone:'Europe/Brussels'}).format(new Date(d+'T12:00:00Z'));
const weekday=d=>fmt(d,{weekday:'short'}).replace('.','');
const KEY='slot-poc-v1';let storageOK=true;function read(){try{return normalizeData(JSON.parse(localStorage.getItem(KEY))||seed())}catch{return normalizeData(seed())}}
let db=read();function save(){try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch{storageOK=false;toast('Opslaan lukt niet. Schakel browseropslag in.');return false}}
const params=new URLSearchParams(location.search);let tenantId=db.tenants.some(t=>t.id===params.get('tenant'))?params.get('tenant'):'lune';let page='overview';let week=TODAY();while(dayOf(week)!==1)week=addDays(week,1);let selectedDay=week;let calWeek=week;let book=null;let isBook=params.get('mode')==='book';let filterText='';let filterStatus='all';let widgetMode='drawer';let mobile=false;const dialog=document.getElementById('modal');let returnFocus=null;
const tenant=()=>db.tenants.find(t=>t.id===tenantId)||db.tenants[0];const bookings=()=>db.bookings.filter(b=>b.tenant===tenantId);const currentBookings=()=>bookings().filter(b=>b.status!=='Geannuleerd');const sorted=a=>[...a].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
const button=(label,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-act="${action}" ${extra}>${label}</button>`;
const badge=(text,cls='')=>`<span class="status ${cls}">${esc(text)}</span>`;
const toggle=(name,value,label='')=>`<label class="switch"><input type="checkbox" name="${name}" ${value?'checked':''} aria-label="${esc(label||name)}"><span></span></label>`;
const tile=(s,media=true)=>`<div class="service-tile">${media&&safeURL(s.image)?`<img src="${esc(safeURL(s.image))}" alt="" loading="lazy" onerror="this.hidden=true">`:icon(s.icon)}</div>`;
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),4000)}
const titles={overview:'Overzicht',calendar:'Agenda',bookings:'Boekingen',services:'Diensten',widget:'Boekingswidget',emails:'E-mails',tracking:'Tracking',settings:'Instellingen',crm:'Mini CRM',agency:'Klanten beheren',roadmap:'Bouwplan'};
function header(title,sub,action='',eyebrow=''){return `<div class="heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}
function shell(){const t=tenant();const navs=[['overview','grid'],['calendar','calendar'],['bookings','list'],['services','layers'],['crm','kanban'],['widget','code'],['emails','mail'],['tracking','chart'],['settings','settings']].filter(([p])=>p!=='crm'||t.features.crm).filter(([p])=>p!=='tracking'||t.features.tracking);document.getElementById('app').innerHTML=`<div class="shell"><div class="mobile-shade ${mobile?'open':''}" data-act="mobile"></div><aside class="sidebar ${mobile?'open':''}"><div class="brand"><span class="brandmark" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span class="brand-copy"><span class="brand-name">afspraakboeken<span class="brand-domain">.be</span></span></span></div><div class="tenant-switch"><span class="avatar">${esc(t.initials)}</span><div style="min-width:0;flex:1"><select id="tenant-switch" aria-label="Wissel demoaccount">${db.tenants.map(x=>`<option value="${x.id}" ${x.id===tenantId?'selected':''}>${esc(x.name)}</option>`).join('')}</select><small>Klantomgeving</small></div></div><div class="nav-label">Werkruimte</div><nav class="nav" aria-label="Klantomgeving">${navs.map(([p,i])=>`<button data-page="${p}" class="${page===p?'active':''}">${icon(i)}${titles[p]}${p==='bookings'?`<span class="badge">${currentBookings().length}</span>`:''}${p==='crm'?'<span class="badge">BÈTA</span>':''}</button>`).join('')}</nav><div class="nav-label">Agency</div><nav class="nav" aria-label="Agency"><button data-page="agency" class="${page==='agency'?'active':''}">${icon('users')}Superadmin</button></nav><div class="sidebar-foot"><div class="plan-card"><p>Eén systeem. Jouw uitstraling.</p><button class="link" data-page="roadmap">Bekijk het bouwplan </button></div><div class="profile"><div class="avatar">JIJ</div><div><strong>Jouw agency</strong><br><small>Superadmin · demo</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-toggle" data-act="mobile" aria-label="Menu openen">${icon('menu')}</button><span>Werkruimte</span><b>${titles[page]}</b></div><div class="top-actions"><span class="demo-tag"><i class="dot"></i>Interactief prototype</span><button class="text-btn" data-act="preview">Bekijk boekingsflow </button></div></header><main class="main" id="main">${renderPage()}</main></div></div>`;}
function renderPage(){return ({overview,services:servicesPage,bookings:bookingsPage,calendar:calendarPage,settings:settingsPage,widget:widgetPage,emails:emailsPage,tracking:trackingPage,agency:agencyPage,crm:crmPage,roadmap:roadmapPage}[page]||overview)()}
function overview(){const t=tenant();const upcoming=currentBookings().filter(b=>b.date>=TODAY()&&b.date<addDays(TODAY(),7));const items=sorted(currentBookings().filter(b=>b.date===selectedDay));const weekEnd=addDays(week,6);return `${header(`Goed geregeld, ${esc(t.name)}.`, 'Alle ruimte voor je klanten. De rest staat hier.',button(icon('plus')+' Nieuwe boeking','preview','primary'),'JOUW WERKRUIMTE')}<div class="stats">${[['Boekingen','calendar',upcoming.length,'In de komende 7 dagen'],['Boekingswaarde','euro',money(upcoming.reduce((n,b)=>n+b.price,0)),'Geplande waarde · geen betalingen'],['Actieve diensten','layers',t.services.filter(s=>s.active).length,'Zichtbaar in je boekingswidget'],['Via campagnes','chart',upcoming.filter(b=>['Facebook','Instagram','Google'].includes(b.source)).length,'Van je komende boekingen']].map(([l,i,n,d])=>`<div class="stat"><div class="stat-top">${l}${icon(i)}</div><div class="stat-number">${n}</div><small>${d}</small></div>`).join('')}</div><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h2>Je week in één oogopslag</h2><p class="sub" style="font-size:10px">${fmt(week)} – ${fmt(weekEnd,{day:'numeric',month:'long',year:'numeric'})}</p></div><div class="flex"><button class="btn small calendar-nav" data-act="week-prev" aria-label="Vorige week">Vorige</button><button class="btn small calendar-nav" data-act="week-next" aria-label="Volgende week">Volgende</button></div></div><div class="week-strip">${Array.from({length:7},(_,i)=>{const d=addDays(week,i);return `<button class="day-card ${d===selectedDay?'active':''}" data-act="select-day" data-date="${d}"><small>${weekday(d)}</small><strong>${Number(d.slice(8))}</strong><i class="dot" style="opacity:${currentBookings().some(b=>b.date===d)?1:.15}"></i></button>`}).join('')}</div><div class="appt-list">${items.length?items.map(b=>`<div class="appt"><time>${b.time}<br><small style="font-size:9px">${clock(minutes(b.time)+b.duration)}</small></time><span class="rail"></span><div><h3>${esc(b.serviceName)}</h3><p>${esc(b.name)} · ${b.duration} min</p></div><div class="end"><button class="text-btn" data-act="booking-detail" data-id="${b.id}">Bekijken</button><div style="margin-top:6px">${money(b.price)}</div></div></div>`).join(''):`<div class="empty">${icon('sun')}${t.blocks.includes(selectedDay)?'Deze dag is geblokkeerd.':'Een beetje ademruimte. Geen boekingen op deze dag.'}</div>`}</div><div class="panel-footer"><span>${items.length} afspraken · ${fmt(selectedDay,{weekday:'long'})}</span><button class="link" data-page="calendar">Volledige agenda </button></div></section><section class="panel services-mini"><div class="panel-head"><h2>Jouw diensten</h2><button class="link" data-page="services">Beheren </button></div>${t.services.slice(0,3).map(s=>`<div class="service-row">${tile(s)}<div><h3>${esc(s.name)}</h3><small>${s.duration} min · ${esc(s.category)}</small></div><span class="price">${t.features.prices?money(s.price):'Op aanvraag'}</span>${badge(s.active?'Actief':'Verborgen',s.active?'':'grey')}</div>`).join('')}</section></div><div class="dashboard-side"><section class="greeting"><div class="eyebrow">Minder regelen, meer doen</div><h2>Meer tijd voor<br>je klanten.</h2><p>Laat je klanten zelf hun moment kiezen. Eenvoudig, in 3 stappen.</p>${button('Probeer je boekingsflow '+'','preview','dark small')}</section><section class="panel"><div class="panel-head"><h2>Waar komen ze vandaan?</h2></div><div class="panel-body"><p class="muted" style="font-size:10px">Bron van alle actieve demoboekingen</p>${['Website','Facebook','Google','Instagram'].map((s,i)=>{const n=currentBookings().filter(b=>b.source===s).length;return `<div class="source-row"><span class="source-icon">${['','f','G','◎'][i]}</span><span>${s}</span><div class="bar"><i style="width:${n/Math.max(1,currentBookings().length)*100}%"></i></div><b>${n}</b></div>`}).join('')}<div style="border-top:1px solid var(--line);padding-top:18px;margin-top:22px"><button class="link" data-page="tracking">Bekijk tracking </button></div></div></section></div></div><div class="bottom-note"><span>${icon('lock')}Demo · alleen opgeslagen in deze browser</span><span>Gemaakt voor rust. Ontworpen om te boeken.</span></div>`}
function servicesPage(){return `${header('Diensten die voor je werken.','Eén helder aanbod. Je klanten kiezen zelf hun moment.',button(icon('plus')+' Dienst toevoegen','service-new','primary'))}<div class="grid-3">${tenant().services.map(s=>`<article class="service-card"><div class="corner">${badge(s.active?'Boekbaar':'Verborgen',s.active?'':'grey')}</div>${tile(s)}<small>${esc(s.category)}</small><h2>${esc(s.name)}</h2><p>${esc(s.description)}</p><div class="flex between" style="font-size:12px;margin-bottom:18px"><span>${s.duration} min <span class="muted">+ ${s.buffer} min buffer</span></span><strong>${tenant().features.prices?money(s.price):'Prijs verborgen'}</strong></div><footer><button class="link" data-act="service-edit" data-id="${s.id}">${icon('edit')}Bewerken</button><button class="link" data-act="service-toggle" data-id="${s.id}">${s.active?'Verbergen':'Zichtbaar maken'}</button></footer></article>`).join('')||'<div class="empty">Voeg je eerste dienst toe.</div>'}</div>`}
function bookingsPage(){const list=sorted(bookings().filter(b=>(filterStatus==='all'||b.status===filterStatus)&&`${b.name} ${b.serviceName} ${b.email}`.toLowerCase().includes(filterText.toLowerCase())));return `${header('Elke afspraak, op één plek.','Van eerste klik tot een warm welkom.',button(icon('plus')+' Nieuwe boeking','preview','primary'))}<div class="toolbar"><input id="booking-search" placeholder="Zoek op naam, e-mail of dienst…" aria-label="Boekingen zoeken" value="${esc(filterText)}"><select id="status-filter" aria-label="Filter op status" style="width:170px"><option value="all">Alle statussen</option><option ${filterStatus==='Bevestigd'?'selected':''}>Bevestigd</option><option ${filterStatus==='Geannuleerd'?'selected':''}>Geannuleerd</option></select></div><div class="panel table-wrap"><table><thead><tr><th>Klant</th><th>Dienst</th><th>Wanneer</th><th>Herkomst</th><th>Status</th><th></th></tr></thead><tbody>${list.map(b=>`<tr><td><strong>${esc(b.name)}</strong><small>${esc(b.email)}</small></td><td>${esc(b.serviceName)}<small>${b.duration} min · ${money(b.price)}</small></td><td>${fmt(b.date)}<small>${b.time} · Europe/Brussels</small></td><td>${esc(b.source)}</td><td>${badge(b.status,b.status==='Geannuleerd'?'red':'')}</td><td><button class="icon-btn" data-act="booking-detail" data-id="${b.id}" aria-label="Boeking van ${esc(b.name)} bekijken">Bekijken</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Geen boekingen gevonden.</td></tr>'}</tbody></table></div>`}
function calendarPage(){const t=tenant();return `${header('Een agenda die met je meewerkt.','Boekbare uren, afspraken en ademruimte.',button(icon('plus')+' Dag blokkeren','block-new','primary'))}<div class="notice">Dit is je lokale demoagenda. Koppelingen met Google Calendar en Microsoft Outlook staan klaar in Instellingen als volgende bouwfase.</div><section class="panel"><div class="panel-head calendar-controls"><div class="flex"><button class="btn small calendar-nav" data-act="cal-prev" aria-label="Vorige week">Vorige</button><h2>${fmt(calWeek)} – ${fmt(addDays(calWeek,4))}</h2><button class="btn small calendar-nav" data-act="cal-next" aria-label="Volgende week">Volgende</button></div><button class="link" data-page="settings">Beschikbaarheid instellen ${icon('settings')}</button></div><div class="calendar-scroll"><div class="calendar-grid"><div class="cal-head"></div>${Array.from({length:5},(_,i)=>{let d=addDays(calWeek,i);return `<div class="cal-head"><small>${weekday(d)}</small><strong>${Number(d.slice(8))}</strong></div>`}).join('')}<div class="cal-hours">${Array.from({length:9},(_,i)=>`<span>${i+9}:00</span>`).join('')}</div>${Array.from({length:5},(_,i)=>{let d=addDays(calWeek,i);const closed=t.blocks.includes(d)||!t.hours[dayOf(d)].open;return `<div class="cal-col ${closed?'closed':''}">${closed?'<div class="blocked-label">Gesloten</div>':''}${currentBookings().filter(b=>b.date===d&&minutes(b.time)>=540&&minutes(b.time)<1080).map(b=>`<button class="cal-event" data-act="booking-detail" data-id="${b.id}" style="top:${minutes(b.time)-540}px;height:${Math.min(b.duration,1080-minutes(b.time))}px"><strong>${b.time} · ${esc(b.serviceName)}</strong><small>${esc(b.name)}</small></button>`).join('')}</div>`}).join('')}</div></div><div class="panel-footer"><span>Weekoverzicht 09:00–18:00 · alle afspraken via Boekingen</span><div class="legend"><span>● Afspraak</span><span>▧ Gesloten</span></div></div></section>${t.blocks.length?`<div class="section-gap"><h3>Geblokkeerde dagen</h3><div class="flex wrap" style="margin-top:15px">${t.blocks.sort().map(d=>button(`${fmt(d)} ${icon('close')}`,'block-remove','small',`data-date="${d}" aria-label="Blokkering ${fmt(d)} verwijderen"`)).join('')}</div><p class="field-help">Bestaande boekingen blijven staan. Regel eventuele annuleringen apart.</p></div>`:''}`}
function settingsPage(){const t=tenant();return `${header('Op jouw ritme.','De basis voor een agenda die klopt.')}<div class="grid-2"><section class="panel"><div class="panel-head"><h2>Wekelijkse beschikbaarheid</h2>${badge('Europe/Brussels','grey')}</div><form id="hours-form" class="panel-body"><p class="muted" style="font-size:12px;margin-bottom:15px">Eén agenda en één medewerker per account in dit prototype.</p>${[1,2,3,4,5,6,0].map(i=>`<div class="hours-row"><input type="checkbox" name="day${i}" ${t.hours[i].open?'checked':''} aria-label="${['Zondag','Maandag','Dinsdag','Woensdag','Donderdag','Vrijdag','Zaterdag'][i]} open"><span>${['Zondag','Maandag','Dinsdag','Woensdag','Donderdag','Vrijdag','Zaterdag'][i]}</span><input type="time" name="start${i}" value="${t.hours[i].start}" required aria-label="Starttijd ${i}"><span>–</span><input type="time" name="end${i}" value="${t.hours[i].end}" required aria-label="Eindtijd ${i}"></div>`).join('')}<div class="fields section-gap"><label>Minimaal vooraf boeken<select name="notice">${[0,2,12,24,48].map(n=>`<option value="${n}" ${n===t.notice?'selected':''}>${n} uur vooraf</option>`).join('')}</select></label><p class="field-help">Boekbaar tot 60 dagen vooruit. Diensten houden rekening met hun duur en buffer.</p></div><div class="save-row"><button class="btn primary" type="submit">Beschikbaarheid opslaan</button></div></form></section><div><section class="panel"><div class="panel-head"><h2>Je bedrijfsgegevens</h2></div><form id="company-form" class="panel-body fields"><label>Bedrijfsnaam<input name="name" value="${esc(t.name)}" required maxlength="60"></label><label>E-mailadres voor boekingen<input name="email" type="email" value="${esc(t.email)}" required></label><label>Locatie / afspraaktype<input name="location" value="${esc(t.location)}" required maxlength="100"></label><div class="save-row"><button class="btn primary" type="submit">Gegevens opslaan</button></div></form></section><section class="panel section-gap"><div class="panel-head"><h2>Je dagelijkse agenda</h2></div><div class="panel-body"><div class="integration"><h3>${icon('calendar')}Google Calendar</h3><p>Vrij/bezet uitlezen, afspraken toevoegen en wijzigingen verwerken.</p>${button('Bekijk koppelplan '+'','integration-info','small')}</div><div class="integration"><h3>${icon('calendar')}Microsoft Outlook</h3><p>Dezelfde werking via Microsoft Graph. Nog niet gekoppeld.</p>${button('Bekijk koppelplan '+'','integration-info','small')}</div></div></section></div></div>`}
function appBase(){return new URL('./',location.href)}
function widgetCode(){const url=new URL('widget.js',appBase()),b=tenant().branding;return `<script src="${url.href}" data-account="${tenantId}" data-mode="${widgetMode}" data-label="Boek je afspraak" data-primary="${b.primary}" data-secondary="${b.secondary}" data-background="${b.background}" data-font="${b.font}" defer><\/script>`}
function widgetPage(){const t=tenant();return `${header('Voelt als een deel van je website.','Eén widget. Jouw kleuren. In drie stappen geboekt.',button('Boekingsflow openen '+'','preview','primary'))}<div class="grid-2"><div><section class="panel"><div class="panel-head"><h2>Maak het eigen</h2></div><form id="widget-form" class="panel-body fields">${brandingFields(t.branding,t.name,'widget-form',false)}<div><label>Weergave</label><div class="segmented" style="margin-top:9px"><button type="button" data-act="widget-mode" data-mode="drawer" class="${widgetMode==='drawer'?'active':''}">Sidebar</button><button type="button" data-act="widget-mode" data-mode="popup" class="${widgetMode==='popup'?'active':''}">Pop-up</button><button type="button" data-act="widget-mode" data-mode="inline" class="${widgetMode==='inline'?'active':''}">In de pagina</button></div></div><div class="save-row"><button type="submit" class="btn primary">Uitstraling opslaan</button></div></form></section><section class="panel section-gap"><div class="panel-head"><h2>Plaats op je website</h2>${icon('code')}</div><div class="panel-body"><p class="muted" style="font-size:12px">Plak deze code in een HTML-blok in WordPress of een andere website.</p><code class="code" data-widget-code>${esc(widgetCode())}</code><div class="flex wrap">${button(icon('copy')+' Kopieer widgetcode','copy-widget','small')}${button('Losse boekingspagina '+'','open-booking','small')}</div><p class="field-help" style="margin-top:13px">Huisstijl gewijzigd? Sla op en kopieer de widgetcode opnieuw. De privépreview vereist toegang. Deze demo bewaart gegevens per browser; voor echte klanten bouwen we de centrale database en login.</p></div></section></div><div><div class="widget-stage">${brandingPreview(t.branding,t.name,'widget-form')}<span class="widget-caption">Live voorbeeld van je huisstijl</span></div><div class="notice section-gap">Dezelfde kleuren en hetzelfde lettertype komen terug in de pop-up, de sidebar en de losse boekingspagina.</div></div></div>`}

function interpolate(text,b){const t=db.tenants.find(t=>t.id===b.tenant);const values={bedrijf:t.name,voornaam:b.name.split(' ')[0],dienst:b.serviceName,datum:fmt(b.date),tijd:b.time};return text.replace(/{{(bedrijf|voornaam|dienst|datum|tijd)}}/g,(_,k)=>values[k])}
function sampleBooking(){return bookings()[0]||{tenant:tenantId,name:'Emma Voorbeeld',serviceName:tenant().services[0]?.name||'Je dienst',date:week,time:'10:00'}}
function emailsPage(){const t=tenant(),b=sampleBooking();return `${header('Een warm welkom begint hier.','Pas de bevestiging aan zodat ze helemaal als jouw merk voelt.')}<div class="notice">E-mailvoorbeeld · dit prototype verstuurt geen e-mails. Zowel de eindklant als het bedrijf krijgt in de productiefase een eigen bevestiging.</div><div class="grid-2"><section class="panel"><div class="panel-head"><h2>Bevestiging voor de eindklant</h2></div><form id="email-form" class="panel-body fields"><label>Onderwerp<input name="subject" value="${esc(t.subject)}" required maxlength="160"></label><label>Bericht<textarea name="message" rows="10" required>${esc(t.message)}</textarea></label><p class="field-help">Beschikbare velden: {{voornaam}}, {{bedrijf}}, {{dienst}}, {{datum}}, {{tijd}}</p><div class="save-row"><button type="submit" class="btn primary">Opslaan & voorbeeld bijwerken</button></div></form></section><div class="email-preview"><small>AAN EINDKLANT · VOORBEELD</small><p style="margin:12px 0 20px;font-weight:600">${esc(interpolate(t.subject,b))}</p><div class="email-card"><span class="email-brand">${esc(t.name)}</span><p>${esc(interpolate(t.message,b))}</p></div><p class="field-help" style="margin-top:20px">De bedrijfsbevestiging bevat de contactgegevens en afspraakdetails. Je kunt beide bekijken bij een boeking.</p></div></div>`}
function trackingPage(){const t=tenant();const events=db.events.filter(e=>e.tenant_id===tenantId);return `${header('Van eerste klik tot boeking.','Een heldere basis om te zien welke campagnes afspraken opleveren.',button('Test via Facebook '+'','test-campaign','primary'))}<div class="notice">Demo: lokale dataLayer-events, alleen na opt-in. Pixel-, GA4- en GTM-ID’s worden bewaard als configuratie, maar laden hier geen externe trackers.</div><div class="grid-2"><section class="panel"><div class="panel-head"><h2>Tracking per account</h2></div><form id="tracking-form" class="panel-body fields"><label>Meta Pixel ID<input name="pixel" placeholder="Bijvoorbeeld 123456789012345" value="${esc(t.tracking.pixel)}" inputmode="numeric" pattern="[0-9]*"></label><label>GA4 Measurement ID<input name="ga" placeholder="G-XXXXXXXXXX" value="${esc(t.tracking.ga)}" pattern="G-[A-Z0-9]+"></label><label>Google Tag Manager ID<input name="gtm" placeholder="GTM-XXXXXXX" value="${esc(t.tracking.gtm)}" pattern="GTM-[A-Z0-9]+"></label><p class="field-help">In productie koppelen we dit aan de toestemming op de website. Persoonsgegevens en gevoelige behandelinformatie horen niet in dit event.</p><div class="save-row"><button type="submit" class="btn primary">Configuratie opslaan</button></div></form></section><section class="panel"><div class="panel-head"><h2>Event-inspecteur</h2>${badge(events.length+' events','grey')}</div><div class="panel-body"><p class="muted" style="font-size:12px">Na een bevestigde boeking met marketingtoestemming verschijnt hier <code>booking_completed</code>.</p><code class="code">${esc(JSON.stringify(events.at(-1)||{event:'booking_completed',event_id:'unieke-boekings-id',tenant_id:tenantId,value:85,currency:'EUR',source:'facebook',campaign:'demo_najaar'},null,2))}</code><p class="field-help">${events.length?'Laatst gemeten event in deze browser.':'Voorbeeldpayload. Er is nog geen nieuw event gemeten.'} Eén unieke event_id vormt de basis voor ontdubbeling. Deze demo registreert uitsluitend voltooide boekingen.</p></div></section></div><section class="panel section-gap"><div class="panel-head"><h2>Recente demo-events</h2></div><div class="table-wrap"><table><thead><tr><th>Event</th><th>Bron</th><th>Campagne</th><th>Waarde</th></tr></thead><tbody>${events.slice(-10).reverse().map(e=>`<tr><td>booking_completed<small>${esc(e.event_id.slice(0,18))}…</small></td><td>${esc(e.source)}</td><td>${esc(e.campaign||'—')}</td><td>${money(e.value)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Maak een testboeking met opt-in om je event te zien.</td></tr>'}</tbody></table></div></section>`}
function agencyPage(){
 const stats=subscriptionStats(db.tenants);
 return `${header('Jouw klanten. Eén overzicht.','Jij regelt de factuur. Hier beheer je het abonnement en de activatie.',button(icon('plus')+' Klant toevoegen','tenant-new','primary'),'SUPERADMIN')}
 <div class="notice">Facturatie loopt via jouw eigen administratie. Nieuwe accounts starten inactief; jij activeert ze handmatig. In deze demo zijn de rollen en gegevens alleen lokaal aanwezig.</div>
 <div class="stats">${[['Klanten',stats.total,'Alle accounts'],['Maandelijkse klanten',stats.monthly,'Alleen actieve accounts'],['Lifetime-klanten',stats.lifetime,'Alleen actieve accounts'],['Maandelijks afgesproken',money(stats.monthlyValue),'Excl. btw · geen gemeten betalingen']].map(([label,value,note])=>`<div class="stat"><div class="stat-top">${label}</div><div class="stat-number">${value}</div><small>${note}</small></div>`).join('')}</div>
 <div class="grid-3">${db.tenants.map(t=>{const sub=t.subscription,lifetime=sub.type==='lifetime';return `<section class="panel tenant-card">
 <div class="flex between"><div class="flex"><div class="avatar" style="background:${t.branding.secondary};color:${contrastText(t.branding.secondary)}">${esc(t.initials)}</div><div><h2>${esc(t.name)}</h2><p class="sub" style="font-size:11px">${esc(t.sector)}</p></div></div>${badge(t.active?'Actief':'Inactief',t.active?'':'grey')}</div>
 <div class="tenant-palette">${paletteSwatches(t.branding)}${button('Huisstijl','tenant-branding','small',`data-id="${t.id}"`)}</div>
 <div class="subscription-strip">${badge(lifetime?'Lifetime':'Maandelijks',lifetime?'purple':'grey')}<span>${lifetime?'Zolang agencyklant':'Handmatige facturatie'}</span></div>
 <div class="metrics"><div><strong>${t.services.filter(s=>s.active).length}</strong><small>diensten</small></div><div><strong>${db.bookings.filter(b=>b.tenant===t.id&&b.status!=='Geannuleerd').length}</strong><small>boekingen</small></div><div><strong>${money(lifetime?sub.lifetimeAmount:sub.monthlyAmount)}</strong><small>${lifetime?'eenmalig':'per maand'} · excl. btw</small></div></div>
 ${!lifetime&&sub.nextInvoiceOn?`<p class="field-help" style="margin-bottom:15px">Volgende factuur: ${fmt(sub.nextInvoiceOn,{day:'numeric',month:'long',year:'numeric'})}</p>`:''}
 <div class="flex wrap">${button(icon('euro')+' Administratie','tenant-admin','small primary',`data-id="${t.id}"`)}${button(icon('settings')+' Modules','tenant-edit','small',`data-id="${t.id}"`)}</div>
 <button class="link" data-act="tenant-open" data-id="${t.id}" style="margin-top:17px">Klantomgeving </button>
 </section>`}).join('')}</div>`;
}

function crmPage(){return `${header('Een afspraak is pas het begin.','Een klein opvolgbord, direct gekoppeld aan je boekingen.')}<div class="notice">CRM-proef: nieuwe boekingen komen in ‘Nieuw’. Verplaats kaarten met het statusmenu. Dit wijzigt de opvolgfase, niet de afspraak in je agenda.</div><div class="kanban">${['Nieuw','Bevestigd','Afgerond'].map(stage=>{const list=currentBookings().filter(b=>b.stage===stage);return `<section class="kanban-col"><h3>${stage}<span class="muted">${list.length}</span></h3>${list.map(b=>`<article class="lead-card">${badge(b.source,b.source==='Facebook'?'purple':'grey')}<h3>${esc(b.name)}</h3><p>${esc(b.serviceName)}</p><p style="margin-top:11px">${fmt(b.date)} · ${b.time}</p><select data-stage="${b.id}" aria-label="Opvolgfase voor ${esc(b.name)}">${['Nieuw','Bevestigd','Afgerond'].map(x=>`<option ${x===stage?'selected':''}>${x}</option>`).join('')}</select><button class="link" data-act="booking-detail" data-id="${b.id}" style="margin-top:12px">Bekijk boeking </button></article>`).join('')||'<div class="empty" style="font-size:11px">Nog geen kaarten.</div>'}</section>`}).join('')}</div>`}
function roadmapPage(){return `${header('Klein beginnen. Goed kunnen groeien.','Een concreet bouwplan voor jouw eigen boekingsproduct.')}<div class="grid-2"><section class="panel"><div class="panel-head"><h2>Van proof of concept naar product</h2></div><div class="panel-body"><div class="plan-step"><span class="number">01</span><div><h3>Nu · de ervaring valideren</h3><p>Een echte klikbare flow met lokaal opgeslagen diensten, beschikbaarheid, boekingen, accountmodules, e-mailvoorbeelden en CRM-kaarten. Test met één beautyzaak en één installateur.</p></div></div><div class="plan-step"><span class="number">02</span><div><h3>Pilot · veilig met echte klanten</h3><ul><li>Centrale database, bedrijfsaccounts en rollen.</li><li>Agenda via Google of Microsoft, met OAuth.</li><li>Boekingsslot servermatig reserveren; dubbele boekingen afvangen.</li><li>E-mails via wachtrij, met retries en bezorgstatus.</li><li>Annuleren, verplaatsen en herinneringen.</li><li>Publieke widget, domeintoelating en toestemming.</li><li>Bronmeting + marketingevents zonder gevoelige data.</li></ul></div></div><div class="plan-step" style="border:0"><span class="number">03</span><div><h3>Daarna · uitbreiden op echte vraag</h3><p>Meerdere medewerkers, behandelruimtes of toestellen, aanbetalingen, servicegebied, reistijd, CRM-automatisering. Facturatie blijft in jouw eigen administratie.</p></div></div></div></section><div><section class="panel"><div class="panel-head"><h2>Eén centrale motor</h2></div><div class="panel-body"><p class="muted" style="font-size:12px">Doel: een zelfstandig platform op Hostinger Agency Professional, met PHP, één MySQL-database en een eigen login. De huidige demo is een overdraagbare HTML/JS-versie; de backend is nog te bouwen. WordPress krijgt een dunne wrapper of HTML-widget. Elke dienst heeft dezelfde basis; sectorpakketten zetten alleen de relevante modules aan.</p><div class="setting-row"><div><h3>Algemene velden</h3><p>Naam, duur, buffer, prijs, uitleg, media en boekbaarheid.</p></div>${icon('layers')}</div><div class="setting-row"><div><h3>Sectorinstellingen</h3><p>Locatie en woningtype voor installatie. Intake voor beauty. Later eigen intakevelden.</p></div>${icon('settings')}</div><div class="setting-row" style="border:0"><div><h3>Verantwoordelijkheden</h3><p>Jij beheert klanten en modules. Je klant beheert aanbod en agenda. Eindklanten boeken zonder account.</p></div>${icon('users')}</div></div></section><section class="greeting section-gap"><div class="eyebrow">Jouw werkwijze</div><h2>Jij factureert.<br>Wij houden het simpel.</h2><p style="max-width:none">Kies per klant maandelijks of lifetime, stuur je factuur via je eigen administratie en activeer het account handmatig. Je klant krijgt geen extra betaalportaal.</p><small>Lifetime betekent hier: gebruik zolang de klant bij jouw agency blijft. Bedragen en factuurreferenties zijn alleen voor jouw overzicht.</small></section></div></div>`}
function openModal(title,html,cls=''){returnFocus=document.activeElement;if(dialog.open)dialog.close();dialog.className=cls;dialog.style.cssText='';dialog.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-act="close" aria-label="Sluiten">${icon('close')}</button></div><div class="modal-body">${html}</div>`;dialog.showModal()}
function closeModal(){dialog.close();dialog.className='';dialog.style.cssText='';book=null;returnFocus?.focus?.()}
function serviceEditor(id){const s=tenant().services.find(s=>s.id===id)||{id:'',name:'',category:'',duration:30,buffer:15,price:0,description:'',image:'',video:'',active:true};openModal(s.id?'Dienst bewerken':'Nieuwe dienst',`<form id="service-form" data-id="${s.id}" class="fields"><label>Naam van de dienst<input name="name" required maxlength="80" value="${esc(s.name)}"></label><div class="grid-2"><label>Categorie<input name="category" required maxlength="50" value="${esc(s.category)}"></label><label>Prijs (€)<input name="price" type="number" min="0" max="100000" step="0.01" required value="${s.price}"></label></div><div class="grid-2"><label>Duur (minuten)<input name="duration" type="number" min="15" max="480" step="5" required value="${s.duration}"></label><label>Buffer na afspraak<input name="buffer" type="number" min="0" max="180" step="5" required value="${s.buffer}"></label></div><label>Uitleg voor je klant<textarea name="description" required maxlength="2000">${esc(s.description)}</textarea></label>${tenant().features.media?`<label>Afbeelding (https-URL)<input name="image" type="url" value="${esc(s.image)}" placeholder="https://jouwwebsite.be/afbeelding.jpg"></label><label>Video (https-link)<input name="video" type="url" value="${esc(s.video)}" placeholder="https://…"></label>`:''}<label class="check"><input name="active" type="checkbox" ${s.active?'checked':''}>Zichtbaar en boekbaar in de widget</label><div class="save-row">${button('Annuleren','close')}<button type="submit" class="btn primary">Dienst opslaan</button></div></form>`)}
function subscriptionFields(sub){
 const monthly=sub.type!=='lifetime';
 return `<label>Abonnementstype<select name="type"><option value="monthly" ${monthly?'selected':''}>Maandelijks</option><option value="lifetime" ${!monthly?'selected':''}>Lifetime · zolang agencyklant</option></select></label>
 <div data-payment-kind="monthly" ${monthly?'':'hidden'}><label>Maandbedrag (€, excl. btw)<input type="number" name="monthlyAmount" min="0" max="100000" step="0.01" value="${sub.monthlyAmount??79}" required ${monthly?'':'disabled'}></label></div>
 <div data-payment-kind="lifetime" ${monthly?'hidden':''}><label>Eenmalig bedrag (€, excl. btw)<input type="number" name="lifetimeAmount" min="0" max="100000" step="0.01" value="${sub.lifetimeAmount??0}" required ${monthly?'disabled':''}></label><p class="field-help">Gebruik zolang deze klant bij jouw agency blijft. Je kunt het account altijd handmatig deactiveren.</p></div>`;
}
function syncSubscriptionFields(form){
 const type=form.querySelector('select[name="type"]').value;
 form.querySelectorAll('[data-payment-kind]').forEach(section=>{const hidden=section.dataset.paymentKind!==type;section.hidden=hidden;section.querySelectorAll('input').forEach(input=>input.disabled=hidden)});
}
function tenantAdministration(id){
 const t=db.tenants.find(t=>t.id===id);if(!t)return;const sub=t.subscription;
 openModal(`Administratie · ${esc(t.name)}`,`<form id="subscription-form" data-id="${t.id}" class="fields">
 <div class="notice" style="margin-bottom:0">Jij factureert buiten dit platform. Deze gegevens dienen voor jouw eigen overzicht; er worden geen facturen of betaalverzoeken verstuurd.</div>
 <div class="setting-row" style="padding-top:0"><div><h3>Account actief</h3><p>Activeer handmatig na jouw facturatie. Deactiveren stopt nieuwe boekingen.</p></div>${toggle('active',t.active,'Account actief')}</div>
 ${subscriptionFields(sub)}
 <div class="grid-2"><label>Startdatum <span class="muted">(optioneel)</span><input type="date" name="startedOn" value="${esc(sub.startedOn)}"></label><div data-payment-kind="monthly" ${sub.type==='monthly'?'':'hidden'}><label>Volgende factuur <span class="muted">(memo)</span><input type="date" name="nextInvoiceOn" value="${esc(sub.nextInvoiceOn)}" ${sub.type==='monthly'?'':'disabled'}></label></div></div>
 <p class="field-help">Datums zijn interne notities. Ze verlengen, factureren of deactiveren niets automatisch.</p>
 <details class="admin-details"><summary>Facturatiegegevens & interne notities <span>Optioneel</span></summary><div class="fields">
 <label>Factuurreferentie<input name="invoiceReference" value="${esc(sub.invoiceReference)}" maxlength="100" placeholder="Bijvoorbeeld 2026-042"></label>
 <label>Bedrijfsnaam op factuur<input name="legalName" value="${esc(sub.legalName)}" maxlength="150"></label>
 <div class="grid-2"><label>Facturatie-e-mail<input name="billingEmail" type="email" value="${esc(sub.billingEmail)}" maxlength="150"></label><label>Btw-nummer<input name="vatNumber" value="${esc(sub.vatNumber)}" maxlength="50" placeholder="BE…"></label></div>
 <label>Facturatieadres<input name="billingAddress" value="${esc(sub.billingAddress)}" maxlength="200"></label>
 <label>Interne notitie<textarea name="notes" rows="3" maxlength="1000" placeholder="Afspraken, facturatie of opvolging…">${esc(sub.notes)}</textarea></label>
 </div></details>
 <div class="save-row" style="margin-top:0">${button('Annuleren','close')}<button type="submit" class="btn primary">Administratie opslaan</button></div></form>`);
}
function applyBranding(element,branding){for(const [key,value] of Object.entries(brandVariables(branding)))element.style.setProperty(key,value)}
function brandingStyle(branding){return Object.entries(brandVariables(branding)).map(([key,value])=>`${key}:${value}`).join(';')}
function bookingBranding(t){
 const branding={...t.branding};
 if(isBook)for(const key of ['primary','secondary','background']){const value=params.get('theme_'+key);if(isBrandColor(value))branding[key]=value}
 if(isBook&&isBrandFont(params.get('theme_font')))branding.font=params.get('theme_font');
 return normalizeBranding(branding,t.color);
}
function paletteSwatches(branding){return `<span class="palette-swatches" aria-label="Kleurenpalet">${BRAND_COLOR_KEYS.map(key=>{const color=normalizeBranding(branding)[key];return `<i style="background:${color}" title="${{primary:'Hoofdkleur',secondary:'Accentkleur',background:'Achtergrondkleur'}[key]}: ${color}"></i>`}).join('')}</span>`}
function brandingPreview(branding,name,formId){return `<div class="brand-preview booking-theme" data-brand-preview="${formId}" style="${brandingStyle(branding)}"><div class="brand-preview-top"><span class="brand-preview-symbol">${icon('spark')}</span><strong data-brand-name>${esc(name||'Jouw bedrijf')}</strong><span class="brand-preview-caption">VOORBEELD</span></div><div class="brand-preview-steps"><b>1 · Dienst</b><span>2 · Moment</span><span>3 · Gegevens</span></div><h3>Een afspraak, zo geregeld.</h3><p>Kies wat bij jou past. Wij maken tijd voor je.</p><div class="brand-preview-service"><span class="brand-preview-symbol">${icon('calendar')}</span><div><strong>Jouw dienst</strong><small>30 minuten · op afspraak</small></div>${icon('check')}</div><span class="brand-preview-cta">Kies je moment </span><small class="brand-preview-note">Jouw huisstijl, in elke stap.</small></div>`}
function brandingFields(branding,name,formId,preview=true){
 const b=normalizeBranding(branding);
 return `<fieldset class="branding-fields"><legend>Huisstijl</legend><p class="field-help">Drie kleuren zijn genoeg. Tekst op gekleurde knoppen past zich automatisch aan.</p><div class="brand-color-grid">${[['primary','Hoofdkleur','Knoppen & selecties'],['secondary','Accentkleur','Iconen & details'],['background','Achtergrond','Boekingsvenster']].map(([key,label,hint])=>`<div><label for="${formId}-${key}">${label}</label><div class="brand-color-input"><input type="color" value="${b[key]}" data-brand-picker="${key}" aria-label="${label} kiezen"><input id="${formId}-${key}" name="${key}" value="${b[key]}" data-brand-hex="${key}" pattern="#[0-9a-fA-F]{6}" maxlength="7" required spellcheck="false" autocomplete="off" aria-label="${label} hexcode" title="Zes tekens na #, bijvoorbeeld #526b5b"></div><p class="field-help">${hint}</p></div>`).join('')}</div><div class="brand-font-field"><label for="${formId}-font">Hoofdlettertype</label><select id="${formId}-font" name="font">${Object.entries(BRAND_FONTS).map(([key,font])=>`<option value="${key}" ${b.font===key?'selected':''}>${font.label} · ${font.description}</option>`).join('')}</select><p class="field-help">Voor titels, tekst en knoppen in je boekingswidget.</p></div></fieldset>${preview?brandingPreview(b,name,formId):''}`;
}
function updateBrandingPreview(form){
 let branding;try{branding=brandingFromForm(Object.fromEntries(new FormData(form)))}catch{return}
 document.querySelectorAll(`[data-brand-preview="${form.id}"]`).forEach(preview=>{applyBranding(preview,branding);const name=form.querySelector('input[name="name"]');if(name)preview.querySelector('[data-brand-name]').textContent=name.value.trim()||'Jouw bedrijf'});
}
function tenantBrandingEditor(id){
 const t=db.tenants.find(t=>t.id===id);if(!t)return;
 openModal(`Huisstijl · ${esc(t.name)}`,`<form id="branding-form" data-id="${t.id}" class="fields">${brandingFields(t.branding,t.name,'branding-form')}<div class="save-row">${button('Annuleren','close')}<button type="submit" class="btn primary">Huisstijl opslaan</button></div></form>`);
}
function tenantEditor(id){
 const t=db.tenants.find(t=>t.id===id);
 if(!t)return openModal('Nieuwe klant',`<form id="tenant-form" class="fields"><label>Bedrijfsnaam<input name="name" required maxlength="60"></label><label>Sectorpreset<select name="preset"><option value="lune">Beauty & wellness</option><option value="aero">Airco & installatie</option><option value="generic">Algemene dienstverlening</option></select></label>${brandingFields(normalizeBranding(seed().tenants[0].branding,seed().tenants[0].color),'Jouw bedrijf','tenant-form')}${subscriptionFields({type:'monthly',monthlyAmount:79,lifetimeAmount:0})}<div class="notice">Het account start inactief. Regel je factuur en activeer daarna via Administratie.</div><div class="save-row"><button type="submit" class="btn primary">Klant aanmaken</button></div></form>`);
 const labels={prices:['Prijzen tonen','De eindklant ziet de dienstprijs.'],media:['Afbeelding & video','Extra informatie bij een dienst.'],address:['Adres opvragen','Voor afspraken op locatie.'],sectorFields:['Sectorvraag','Woningtype of eerste bezoek.'],notes:['Opmerking','Een korte extra toelichting bij de boeking.'],crm:['Mini CRM','Opvolgbord in de klantomgeving.'],tracking:['Campagnetracking','Configuratie en opt-in voor marketingevents.']};
 openModal(`Modules · ${esc(t.name)}`,`<form id="features-form" data-id="${t.id}"><div class="notice">Bepaal welke functies deze klant te zien krijgt. Abonnement en activatie beheer je apart via Administratie.</div>${Object.entries(labels).map(([k,[label,description]])=>`<div class="setting-row"><div><h3>${label}</h3><p>${description}</p></div>${toggle(k,t.features[k],label)}</div>`).join('')}<div class="save-row"><button type="submit" class="btn primary">Modules opslaan</button></div></form>`);
}

function bookingDetails(id){const b=db.bookings.find(b=>b.id===id);if(!b)return;openModal('Afspraakdetails',`<div class="flex between" style="margin-bottom:24px"><h3>${esc(b.serviceName)}</h3>${badge(b.status,b.status==='Geannuleerd'?'red':'')}</div><div class="details-grid">${[['Klant',b.name],['E-mail',b.email],['Datum',fmt(b.date,{weekday:'long',day:'numeric',month:'long'})],['Tijd',b.time+' · '+b.duration+' min'],['Telefoon',b.phone||'Niet ingevuld'],['Herkomst',b.source],['Adres',b.address||'Niet van toepassing'],['Extra',b.extra||'—'],['Opmerking',b.note||'—'],['CRM-fase',b.stage]].map(([l,v])=>`<div><small>${l}</small><p>${esc(v)}</p></div>`).join('')}</div><div class="notice section-gap">${b.demo?'Voorbeeldboeking met fictieve gegevens.':'Testboeking, lokaal opgeslagen.'} Er zijn geen e-mails verstuurd.</div><div class="save-row wrap">${button(icon('mail')+' E-mailvoorbeelden','booking-emails','',`data-id="${b.id}"`)}${b.status!=='Geannuleerd'?button('Annuleren','cancel-confirm','danger',`data-id="${b.id}"`):''}</div>`)}
function emailDetails(id){const b=db.bookings.find(b=>b.id===id),t=db.tenants.find(t=>t.id===b.tenant);openModal('Bevestigingen · voorbeeld',`<div class="notice">Beide berichten worden alleen getoond. Niets is verzonden.</div><div class="email-preview"><small>AAN ${esc(b.email)}</small><p style="font-weight:600;margin:12px 0">${esc(interpolate(t.subject,b))}</p><div class="email-card"><p>${esc(interpolate(t.message,b))}</p></div></div><div class="email-preview section-gap"><small>AAN ${esc(t.email)}</small><p style="font-weight:600;margin:12px 0">Nieuwe boeking: ${esc(b.serviceName)}</p><div class="email-card"><p>${esc(b.name)} heeft geboekt.\n\n${esc(b.serviceName)}\n${fmt(b.date)} om ${b.time}\n${b.duration} minuten\n\nE-mail: ${esc(b.email)}\nTelefoon: ${esc(b.phone||'—')}\nAdres: ${esc(b.address||'—')}</p></div></div>`)}
function startBooking(campaign=false){const t=tenant();book={step:1,service:null,date:null,time:null,month:TODAY().slice(0,7),info:null,fields:{},source:campaign?'facebook':(params.get('utm_source')||'website'),campaign:campaign?'demo_najaar':(params.get('utm_campaign')||''),confirmed:null,error:''};if(!isBook){returnFocus=document.activeElement;if(dialog.open)dialog.close();dialog.className=widgetMode==='popup'?'booking-theme':'drawer booking-theme';dialog.showModal()}renderBooking()}
function renderBooking(){
 const t=tenant(),branding=bookingBranding(t);
 const currentStep=!t.active?0:book.confirmed?4:book.step;
 const changed=book.renderedStep!==currentStep;
 const motion=changed&&book.renderedStep!==undefined?(currentStep<book.renderedStep?'step-back':'step-forward'):'';
 const revealTimes=!!book.date&&book.renderedDate!==book.date;
 const surface=isBook?document.getElementById('app'):dialog;
 const focused=document.activeElement;
 const focusKey=surface.contains(focused)&&focused?.dataset?.act?{...focused.dataset}:null;
 const scrollTop=surface.scrollTop;
 applyBranding(surface,branding);
 const html=`<div class="demo-banner">Testomgeving · geen echte afspraak of e-mail</div>
 <div class="booking-top"><div class="booking-brand"><span class="avatar">${esc(t.initials)}</span><div><strong>${esc(t.name)}</strong><small>${esc(t.location)}</small></div></div>${!isBook?`<button class="icon-btn" data-act="close" aria-label="Boekingsflow sluiten">${icon('close')}</button>`:''}</div>
 ${!book.confirmed?`<div class="steps" aria-label="Boekingsstappen">${['Dienst','Moment','Gegevens'].map((l,i)=>`${i?'<span class="step-line"></span>':''}<span class="step ${book.step===i+1?'active':book.step>i+1?'done':''}" ${book.step===i+1?'aria-current="step"':''}><i>${book.step>i+1?'✓':i+1}</i>${l}</span>`).join('')}</div>`:''}
 <div class="booking-body ${motion}">${!t.active?'<div class="empty">Dit account neemt momenteel geen nieuwe boekingen aan.</div>':book.confirmed?bookingSuccess():book.step===1?bookingServices():book.step===2?bookingTime(revealTimes):bookingFields()}</div>
 ${t.active?`<div class="booking-footer">${book.confirmed?button('Nog een testboeking maken','book-reset','primary'):book.step===1?'':book.step===2?button('Naar je gegevens '+'','book-next','primary',!book.time?'disabled':''):'<button class="btn primary" form="booking-form" type="submit">Bevestig mijn testafspraak '+icon('check')+'</button>'}<div class="powered">${icon('lock')}Eenvoudig geboekt met <strong>afspraakboeken.be</strong></div></div>`:''}`;
 if(isBook)surface.innerHTML=`<main class="standalone booking-theme"><div class="book-shell">${html}</div></main>`;
 else{dialog.classList.add('booking-theme');dialog.innerHTML=html;}
 book.renderedStep=currentStep;book.renderedDate=book.date;
 if(changed){
  if(isBook)window.scrollTo(0,0);else dialog.scrollTop=0;
  document.getElementById('booking-step-title')?.focus({preventScroll:true});
 }else{
  surface.scrollTop=scrollTop;
  if(focusKey){
   const replacement=[...surface.querySelectorAll('[data-act]')].find(el=>Object.entries(focusKey).every(([key,value])=>el.dataset[key]===value));
   replacement?.focus({preventScroll:true});
  }
 }
}
function bookingServices(){const t=tenant();return `<div class="eyebrow">Een moment voor jou</div><h1 id="booking-step-title" tabindex="-1">Waar kunnen we je mee helpen?</h1><p class="sub">Kies je dienst en bekijk meteen de vrije momenten.</p>${t.services.filter(s=>s.active).map(s=>`<div class="booking-service ${book.service===s.id?'selected':''}">${tile(s,t.features.media)}<div style="flex:1"><button class="select-service" data-act="book-service" data-id="${s.id}" aria-label="${esc(s.name)} kiezen en vrije momenten bekijken"><h3>${esc(s.name)}</h3><small>${s.duration} min${t.features.prices?' &nbsp;·&nbsp; '+(s.price?money(s.price):'Gratis'):''}</small></button><div><button class="text-btn service-info" data-act="book-info" data-id="${s.id}" aria-expanded="${book.info===s.id}">${book.info===s.id?'Minder informatie':'Meer over deze dienst'} </button></div></div><button class="radio-dot" data-act="book-service" data-id="${s.id}" aria-label="${esc(s.name)} kiezen en vrije momenten bekijken" aria-pressed="${book.service===s.id}"></button></div>${book.info===s.id?`<div class="info-inline">${t.features.media&&safeURL(s.image)?`<img src="${esc(safeURL(s.image))}" alt="${esc(s.name)}">`:''}<p>${esc(s.description)}</p>${t.features.media&&safeURL(s.video)?`<a href="${esc(safeURL(s.video))}" target="_blank" rel="noopener noreferrer">Bekijk de video </a>`:''}</div>`:''}`).join('')||'<div class="empty">Er zijn nog geen boekbare diensten.</div>'}`}
function bookingTime(revealTimes=false){const t=tenant(),s=t.services.find(s=>s.id===book.service);const first=book.month+'-01',offset=(dayOf(first)+6)%7;const count=new Date(Number(book.month.slice(0,4)),Number(book.month.slice(5)),0).getDate();const slots=book.date?available(t,s,book.date,db.bookings):[];return `<button class="link" data-act="book-back" style="margin-bottom:18px">Dienst wijzigen</button><h1 id="booking-step-title" tabindex="-1">Wanneer past het voor jou?</h1><p class="sub">Alleen vrije momenten. Meteen duidelijk.</p><div class="booking-summary"><span>${esc(s.name)} · ${s.duration} min</span><strong>${t.features.prices?money(s.price):''}</strong></div><div class="month-head"><button class="btn small calendar-nav" data-act="month-prev" ${book.month<=TODAY().slice(0,7)?'disabled':''} aria-label="Vorige maand">Vorige</button><strong>${fmt(first,{month:'long',year:'numeric'})}</strong><button class="btn small calendar-nav" data-act="month-next" ${book.month>=addDays(TODAY(),60).slice(0,7)?'disabled':''} aria-label="Volgende maand">Volgende</button></div><div class="month-grid">${['ma','di','wo','do','vr','za','zo'].map(d=>`<small>${d}</small>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const d=book.month+'-'+String(i+1).padStart(2,'0');return `<button data-act="book-date" data-date="${d}" ${available(t,s,d,db.bookings).length?'':'disabled'} class="${d===book.date?'selected':''}" aria-label="${fmt(d,{weekday:'long',day:'numeric',month:'long'})}">${i+1}</button>`}).join('')}</div><div class="section-gap"><h3 style="font-size:12px">${book.date?fmt(book.date,{weekday:'long',day:'numeric',month:'long'}):'Selecteer eerst een dag'}</h3>${book.date?`<div class="time-grid ${revealTimes?'times-enter':''}">${slots.map(time=>`<button data-act="book-time" data-time="${time}" class="${time===book.time?'selected':''}">${time}</button>`).join('')}</div>${!slots.length?'<p class="sub" style="font-size:11px">Deze dag is inmiddels vol. Kies een andere dag.</p>':''}`:''}<p class="field-help" style="margin-top:14px">${icon('clock')} Alle tijden: België · Europe/Brussels</p></div>`}
function bookingFields(){const t=tenant(),s=t.services.find(s=>s.id===book.service),f=book.fields;return `<button class="link" data-act="book-back" style="margin-bottom:18px">Moment wijzigen</button><h1 id="booking-step-title" tabindex="-1">Bijna geregeld.</h1><p class="sub">Nog even je gegevens en je afspraak staat.</p><div class="booking-summary"><span>${esc(s.name)}<br><small>${fmt(book.date)} om ${book.time} · ${s.duration} min</small></span><strong>${t.features.prices?money(s.price):''}</strong></div>${book.error?`<div class="error-msg">${esc(book.error)}</div>`:''}<form id="booking-form" class="fields"><label>Volledige naam<input name="name" autocomplete="name" placeholder="Voor- en achternaam" required maxlength="100" value="${esc(f.name||'')}"></label><label>E-mailadres<input name="email" type="email" autocomplete="email" placeholder="jij@voorbeeld.be" required maxlength="150" value="${esc(f.email||'')}"></label><label>Telefoonnummer <span class="muted">(optioneel)</span><input name="phone" type="tel" autocomplete="tel" placeholder="+32 …" maxlength="30" value="${esc(f.phone||'')}"></label>${t.features.address?`<label>Adres van het bezoek<input name="address" autocomplete="street-address" placeholder="Straat, nummer, postcode en gemeente" required maxlength="200" value="${esc(f.address||'')}"></label>`:''}${t.features.sectorFields?`<label>${t.features.address?'Type locatie':'Is dit je eerste bezoek?'}<select name="extra" required><option value="">Maak een keuze</option>${(t.features.address?['Woning','Appartement','Handelszaak']:['Ja, mijn eerste bezoek','Nee, ik ben al klant']).map(x=>`<option ${f.extra===x?'selected':''}>${x}</option>`).join('')}</select></label>`:''}${t.features.notes?`<label>Wil je nog iets meegeven? <span class="muted">(optioneel)</span><textarea name="note" placeholder="Een korte toelichting…" maxlength="1000" rows="2" style="min-height:65px">${esc(f.note||'')}</textarea></label>`:''}<p class="field-help">Gebruik fictieve gegevens. Deze test slaat je boeking alleen in deze browser op. Er gaat geen e-mail uit.</p>${t.features.tracking?`<label class="check" style="align-items:flex-start"><input name="marketing" type="checkbox" ${f.marketing?'checked':''}><span style="font-size:10px;line-height:1.6;color:var(--muted)">Ik sta marketingmeting toe. In deze demo wordt alleen een lokaal conversie-event geregistreerd. Optioneel.</span></label>`:''}</form>`}
function bookingSuccess(){const b=book.confirmed;return `<div class="success"><div class="success-icon">${icon('check')}</div><h1 id="booking-step-title" tabindex="-1">Helemaal geregeld, ${esc(b.name.split(' ')[0])}.</h1><p>Je testafspraak staat in de demoagenda.<br>We kijken uit naar je bezoek.</p><div class="success-card"><div class="flex">${icon('spark')}<strong>${esc(b.serviceName)}</strong></div><div class="flex">${icon('calendar')}<span>${fmt(b.date,{weekday:'long',day:'numeric',month:'long'})} om ${b.time}</span></div><div class="flex">${icon('clock')}<span>${b.duration} minuten · Europe/Brussels</span></div><div class="flex">${icon('pin')}<span>${esc(b.address||tenant().location)}</span></div></div><div class="notice">Testboeking opgeslagen. Geen echte afspraak, agendasynchronisatie of e-mailverzending.</div><div class="flex wrap" style="justify-content:center">${button(''+' Agenda (.ics)','download-ics','small',`data-id="${b.id}"`)}${!isBook?button('Bekijk in agenda '+'','go-booking','small',`data-id="${b.id}"`):''}</div></div>`}
function finishBooking(form){const f=Object.fromEntries(new FormData(form));book.fields=f;db=read();const t=tenant(),s=t.services.find(s=>s.id===book.service);if(!s||!available(t,s,book.date,db.bookings).includes(book.time)){book.error='Dit moment is niet meer beschikbaar. Kies een nieuw moment.';book.step=2;book.time=null;renderBooking();toast(book.error);return}const b={id:crypto.randomUUID(),tenant:tenantId,service:s.id,serviceName:s.name,duration:s.duration,buffer:s.buffer,price:s.price,name:f.name.trim(),email:f.email.trim(),phone:f.phone?.trim()||'',address:f.address?.trim()||'',extra:f.extra||'',note:f.note?.trim()||'',date:book.date,time:book.time,status:'Bevestigd',source:'Onbekend (geen opt-in)',campaign:'',stage:'Nieuw',demo:false};if(!b.name){toast('Vul je naam in.');return}const consent=t.features.tracking&&!!f.marketing;let event;if(consent){const src=book.source.toLowerCase().replace(/[^a-z0-9_-]/g,'').slice(0,50)||'website';b.source=({facebook:'Facebook',instagram:'Instagram',google:'Google',website:'Website'})[src]||src;b.campaign=book.campaign.replace(/[^a-zA-Z0-9_-]/g,'').slice(0,80);event={event:'booking_completed',event_id:b.id,tenant_id:tenantId,value:b.price,currency:'EUR',source:src,campaign:b.campaign};db.events.push(event)}db.bookings.push(b);if(!save()){db=read();book.error='Je boeking kon niet worden opgeslagen. Probeer opnieuw met browseropslag ingeschakeld.';renderBooking();return}if(event){window.dataLayer=window.dataLayer||[];window.dataLayer.push(event);const origin=safeURL(params.get('parent'));if(window.parent!==window&&origin){window.parent.postMessage({type:'slot:booking_completed',event},new URL(origin).origin)}}book.confirmed=b;if(!isBook)shell();renderBooking();}
function downloadICS(b){const stamp=(d,t)=>new Date(epoch(d,t)).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const end=clock(minutes(b.time)+b.duration);const clean=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Afspraakboeken.be//Demo//NL','BEGIN:VEVENT',`UID:${b.id}@slot-demo`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART:${stamp(b.date,b.time)}`,`DTEND:${stamp(b.date,end)}`,`SUMMARY:${clean('[TEST] '+b.serviceName)}`,`DESCRIPTION:${clean('Testafspraak uit het Afspraakboeken.be prototype. Geen echte boeking.')}`,'END:VEVENT','END:VCALENDAR'].join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='afspraakboeken-testafspraak.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function action(a,el){const id=el.dataset.id,t=tenant();switch(a){case'mobile':mobile=!mobile;shell();break;case'close':closeModal();break;case'preview':startBooking();break;case'test-campaign':startBooking(true);break;case'book-reset':startBooking();break;case'select-day':selectedDay=el.dataset.date;shell();break;case'week-prev':case'week-next':week=addDays(week,a==='week-prev'?-7:7);selectedDay=week;shell();break;case'cal-prev':case'cal-next':calWeek=addDays(calWeek,a==='cal-prev'?-7:7);shell();break;case'service-new':serviceEditor();break;case'service-edit':serviceEditor(id);break;case'service-toggle':{const s=t.services.find(s=>s.id===id);s.active=!s.active;save();shell();toast(s.active?'Dienst is boekbaar.':'Dienst verborgen. Bestaande boekingen blijven staan.');break}case'tenant-new':tenantEditor();break;case'tenant-edit':tenantEditor(id);break;case'tenant-admin':tenantAdministration(id);break;case'tenant-branding':tenantBrandingEditor(id);break;case'tenant-open':tenantId=id;widgetMode=tenant().widgetMode||'drawer';page='overview';shell();break;case'booking-detail':bookingDetails(id);break;case'booking-emails':emailDetails(id);break;case'cancel-confirm':openModal('Testboeking annuleren',`<p>Het tijdslot komt weer vrij. Er wordt geen annuleringsmail verstuurd.</p><div class="save-row">${button('Terug','booking-detail','',`data-id="${id}"`)}${button('Afspraak annuleren','cancel-booking','danger',`data-id="${id}"`)}</div>`);break;case'cancel-booking':db.bookings.find(b=>b.id===id).status='Geannuleerd';save();closeModal();shell();toast('Testboeking geannuleerd; het tijdslot is weer vrij.');break;case'block-new':openModal('Dag blokkeren',`<form id="block-form" class="fields"><label>Datum<input type="date" name="date" min="${TODAY()}" required value="${addDays(TODAY(),2)}"></label><p class="field-help">Deze hele dag wordt onboekbaar. Bestaande afspraken worden niet automatisch geannuleerd.</p><div class="save-row"><button type="submit" class="btn primary">Dag blokkeren</button></div></form>`);break;case'block-remove':t.blocks=t.blocks.filter(d=>d!==el.dataset.date);save();shell();toast('Dag weer beschikbaar volgens je openingsuren.');break;case'integration-info':openModal('Van demoagenda naar echte agenda',`<div class="notice">Nog geen agenda verbonden. Deze knop start geen OAuth-koppeling.</div><div class="fields"><p>In de pilot verbindt de klant Google Calendar of Microsoft Outlook met zijn eigen account.</p><p>We lezen bezette momenten uit, houden rekening met dienstduur en buffer, en schrijven nieuwe boekingen terug naar de gekozen agenda. Handmatige blokkeringen krijgen ook een agenda-item.</p><p>Wijzigingen worden via webhooks en periodieke controles verwerkt. Kort vóór bevestiging controleren we de beschikbaarheid opnieuw en reserveren we het tijdslot in de centrale database.</p><p>Bij een verlopen verbinding tonen we een waarschuwing en sluiten we automatisch boeken tijdelijk af. We voorkomen lussen met een vaste koppeling tussen boeking en extern agenda-item.</p><p class="muted">Eerste pilot: één agenda per bedrijf. Meerdere medewerkers en gedeelde ruimtes volgen later.</p></div>`);break;case'widget-mode':widgetMode=el.dataset.mode;t.widgetMode=widgetMode;save();document.querySelectorAll('[data-act="widget-mode"]').forEach(button=>button.classList.toggle('active',button.dataset.mode===widgetMode));document.querySelector('[data-widget-code]').textContent=widgetCode();break;case'copy-widget':try{await navigator.clipboard.writeText(widgetCode());toast('Widgetcode gekopieerd.')}catch{openModal('Widgetcode',`<textarea readonly rows="6">${esc(widgetCode())}</textarea>`)}break;case'open-booking':window.open(`${appBase().href}?mode=book&tenant=${encodeURIComponent(tenantId)}`,'_blank','noopener');break;case'book-service':if(!book||book.step!==1||!t.active||!t.services.some(s=>s.id===id&&s.active))break;if(book.service!==id){book.date=null;book.time=null}book.service=id;book.info=null;book.error='';book.step=2;renderBooking();break;case'book-info':book.info=book.info===id?null:id;renderBooking();break;case'book-next':if(book.step===2&&book.time)book.step=3;renderBooking();break;case'book-back':if(book.step<=1)break;if(book.step===3){const f=document.getElementById('booking-form');book.fields=Object.fromEntries(new FormData(f))}book.step--;renderBooking();break;case'book-date':book.date=el.dataset.date;book.time=null;renderBooking();break;case'book-time':book.time=el.dataset.time;renderBooking();break;case'month-prev':case'month-next':{const d=new Date(book.month+'-15T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+(a==='month-next'?1:-1));book.month=d.toISOString().slice(0,7);renderBooking();break}case'download-ics':downloadICS(db.bookings.find(b=>b.id===id));break;case'go-booking':{const b=db.bookings.find(b=>b.id===id);closeModal();page='calendar';calWeek=b.date;while(dayOf(calWeek)!==1)calWeek=addDays(calWeek,-1);shell();break}}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-act],[data-page]');if(!el)return;if(el.dataset.page){page=el.dataset.page;mobile=false;shell();window.scrollTo(0,0)}else action(el.dataset.act,el)});
document.addEventListener('change',e=>{const el=e.target;if(el.name==='font'&&['tenant-form','branding-form','widget-form'].includes(el.form?.id)){el.form.dataset.brandingEdited='true';updateBrandingPreview(el.form);return}if(el.name==='preset'&&el.form?.id==='tenant-form'&&!el.form.dataset.brandingEdited){const preset=normalizeData(seed()).tenants[el.value==='aero'?1:0];for(const key of BRAND_COLOR_KEYS){const value=preset.branding[key];el.form.querySelector(`[name="${key}"]`).value=value;el.form.querySelector(`[data-brand-picker="${key}"]`).value=value}updateBrandingPreview(el.form);return}if(el.name==='type'&&['tenant-form','subscription-form'].includes(el.form?.id)){syncSubscriptionFields(el.form);return}if(el.id==='tenant-switch'){tenantId=el.value;widgetMode=tenant().widgetMode||'drawer';if((page==='crm'&&!tenant().features.crm)||(page==='tracking'&&!tenant().features.tracking))page='overview';shell()}if(el.id==='status-filter'){filterStatus=el.value;shell()}if(el.dataset.stage){db.bookings.find(b=>b.id===el.dataset.stage).stage=el.value;save();shell();toast('Opvolgfase bijgewerkt.')}});
document.addEventListener('input',e=>{const el=e.target,form=el.form,key=el.dataset.brandPicker||el.dataset.brandHex;if(form&&key){form.dataset.brandingEdited='true';if(el.dataset.brandPicker)form.querySelector(`[name="${key}"]`).value=el.value;else if(isBrandColor(el.value))form.querySelector(`[data-brand-picker="${key}"]`).value=el.value;updateBrandingPreview(form);return}if(form?.id==='tenant-form'&&el.name==='name')updateBrandingPreview(form);if(e.target.id==='booking-search'){const pos=e.target.selectionStart;filterText=e.target.value;document.getElementById('main').innerHTML=bookingsPage();const input=document.getElementById('booking-search');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(!form.reportValidity())return;const f=Object.fromEntries(new FormData(form)),t=tenant();switch(form.id){case'booking-form':finishBooking(form);return;case'service-form':{const old=t.services.find(s=>s.id===form.dataset.id);const s={...old,id:old?.id||crypto.randomUUID(),name:f.name.trim(),category:f.category.trim(),duration:Number(f.duration),buffer:Number(f.buffer),price:Number(f.price),description:f.description.trim(),image:'image'in f?safeURL(f.image):old?.image||'',video:'video'in f?safeURL(f.video):old?.video||'',active:!!f.active,icon:old?.icon||'spark'};if(!s.name||!s.category||!s.description)return toast('Vul naam, categorie en uitleg in.');if(old)t.services[t.services.indexOf(old)]=s;else t.services.push(s);save();closeModal();shell();toast('Dienst opgeslagen.');return}case'block-form':if(!t.blocks.includes(f.date))t.blocks.push(f.date);save();closeModal();shell();toast('Dag geblokkeerd voor nieuwe boekingen.');return;case'hours-form':{for(let i=0;i<7;i++)if(f['day'+i]&&f['start'+i]>=f['end'+i])return toast('De eindtijd moet na de begintijd liggen.');for(let i=0;i<7;i++)t.hours[i]={open:!!f['day'+i],start:f['start'+i],end:f['end'+i]};t.notice=Number(f.notice);break}case'company-form':if(!f.name.trim()||!f.location.trim())return toast('Vul de bedrijfsgegevens in.');t.name=f.name.trim();t.email=f.email;t.location=f.location.trim();break;case'widget-form':case'branding-form':{const x=form.id==='branding-form'?db.tenants.find(x=>x.id===form.dataset.id):t;if(!x)return;let branding;try{branding=brandingFromForm(f,x.branding)}catch(error){toast(error.message);return}const previous=x.branding,previousColor=x.color;x.branding=branding;x.color=branding.primary;if(!save()){x.branding=previous;x.color=previousColor;return}if(form.id==='branding-form')closeModal();shell();toast('Huisstijl opgeslagen voor '+x.name+'.');return}case'email-form':t.subject=f.subject;t.message=f.message;break;case'tracking-form':t.tracking={pixel:f.pixel,ga:f.ga,gtm:f.gtm};break;case'features-form':{const x=db.tenants.find(x=>x.id===form.dataset.id);for(const k of Object.keys(x.features))x.features[k]=!!f[k];save();closeModal();shell();toast('Modules opgeslagen.');return}case'subscription-form':{const x=db.tenants.find(x=>x.id===form.dataset.id);if(!x)return;let subscription;try{subscription=subscriptionFromForm(f,x.subscription)}catch(error){toast(error.message);return}const previous=x.subscription,wasActive=x.active;x.subscription=subscription;x.active=!!f.active;if(!save()){x.subscription=previous;x.active=wasActive;return}closeModal();shell();toast('Administratie opgeslagen. '+(x.active?'Account actief.':'Account inactief.'));return}case'tenant-form':{const base=structuredClone(normalizeData(seed()).tenants[f.preset==='aero'?1:0]);base.id=crypto.randomUUID();base.name=f.name.trim();if(!base.name)return toast('Vul een bedrijfsnaam in.');base.initials=base.name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();try{base.subscription=subscriptionFromForm(f)}catch(error){toast(error.message);return}try{base.branding=brandingFromForm(f,base.branding);base.color=base.branding.primary}catch(error){toast(error.message);return}base.active=false;delete base.plan;base.email='demo@example.com';base.blocks=[];if(f.preset==='generic'){base.sector='Dienstverlening';base.services=[];base.features.sectorFields=false;base.location='Op afspraak';}db.tenants.push(base);if(!save()){db.tenants.pop();return}closeModal();shell();tenantAdministration(base.id);toast('Klant aangemaakt. Activeer wanneer jij klaar bent.');return}default:return}if(save()){shell();toast('Wijzigingen opgeslagen.')}});
dialog.addEventListener('cancel',()=>{book=null;returnFocus?.focus?.()});window.addEventListener('storage',e=>{if(e.key===KEY){db=read();if(book)renderBooking();else if(!isBook)shell()}});
try{if(!localStorage.getItem(KEY))save()}catch{storageOK=false}widgetMode=tenant().widgetMode||'drawer';if(isBook)startBooking();else shell();
